    "profile.confirm.reset": { zh: "清除当前派生画像并从现在起重新维护。旧 Timeline 仅在手动历史重建时参与。", en: "Clear the derived profile and maintain it from now on. Old Timelines return only through a manual rebuild.", ru: "Очистить производный профиль и продолжить с текущего момента. Старые Timeline вернутся только при ручной пересборке." },
